 "content": "from collections import Counter, deque


def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            out.append((color, cells))
    return out


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = components(grid)
    markers = []
    for i, (color, cells) in enumerate(comps):
        if color == bg or len(cells) < 3:
            continue
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        s = set(cells)
        shapes = [
            ({(r0, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)}, 1, 1),
            ({(r0, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}, 1, -1),
            ({(r1, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)}, -1, 1),
            ({(r1, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)}, -1, -1),
        ]
        for shape, dr, dc in shapes:
            if s == shape:
                markers.append((len(cells), i, color, cells, r0, r1, c0, c1, dr, dc))
                break
    if not markers:
        return [row[:] for row in grid]
    # The indicator is the smallest L-like component; its open diagonal selects the target.
    _, mi, marker_color, mcells, r0, r1, c0, c1, dr, dc = min(markers)
    mr = sum(r for r, c in mcells) / len(mcells)
    mc = sum(c for r, c in mcells) / len(mcells)
    candidates = []
    for j, (color, cells) in enumerate(comps):
        if j == mi or color == bg or color == marker_color:
            continue
        cr = sum(r for r, c in cells) / len(cells)
        cc = sum(c for r, c in cells) / len(cells)
        if (cr - (r0 + r1) / 2) * dr > 0 and (cc - (c0 + c1) / 2) * dc > 0:
            dist = min(abs(r - rr) + abs(c - cc0) for r, c in cells for rr, cc0 in mcells)
            candidates.append((dist, j))
    if not candidates:
        return [row[:] for row in grid]
    _, j = min(candidates)
    out = [row[:] for row in grid]
    for r, c in comps[j][1]:
        out[r][c] = marker_color
    return out
